var n=`0865-haleem`;var t=`world-0865`;var a=`PK`;var s=`south-asia`;var r=4;var l=470;var o={en:`Haleem`,ua:`Халім`};var g={en:`Haleem is a Pakistan dish made with wheat berries, barley grain, green lentils, lamb shoulder. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Халім, страва кухні країни Пакистан. Основні складники: зерна пшениці, зерно ячменю, зелена сочевиця, лопатка ягняти. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Soak dried legumes in plenty of cool water for 240 minutes, then drain and discard the soaking water. Cook them fully in fresh water.`,ua:`Замочіть сухі бобові у великій кількості прохолодної води на 240 хвилин, потім злийте та вилийте воду від замочування. Повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:240,i:[[`wheat-berries`,130,`g`],[`barley-grain`,90,`g`],[`green-lentils`,80,`g`],[`water`,1e3,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 65 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 65 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:65,i:[[`water`,1300,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 115 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 115 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:115,i:[[`lamb-shoulder`,650,`g`],[`yellow-onion`,170,`g`],[`ginger-garlic-paste`,26,`g`],[`ghee`,55,`g`],[`garam-masala`,9,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:12,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`water`,380,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`lemon`,1,`pcs`]]}];var m={slug:n,id:t,country:`PK`,region:s,servings:4,minutes:470,title:o,text:g,steps:d};export{a as country,m as default,t as id,l as minutes,s as region,r as servings,n as slug,d as steps,g as text,o as title};